def load_module(path: Path, module_name: str):
    spec = importlib.util.spec_from_file_location(module_name, path)

    if spec is None or spec.loader is None:
        raise RuntimeError(f"Cannot load Python module: {path}")

    module = importlib.util.module_from_spec(spec)

    # Register the module before execution.
    # Required for dataclasses and other module introspection.
    sys.modules[module_name] = module

    try:
        spec.loader.exec_module(module)
    except Exception:
        sys.modules.pop(module_name, None)
        raise

    return module

def main() -> None:
    if not DATASET_PATH.is_file():
        raise SystemExit("Run this script from the CodeGraphRAG project root.")
    if BACKUP_PATH.exists():
        raise SystemExit(f"Backup already exists: {BACKUP_PATH}. No changes made.")

    original = DATASET_PATH.read_text(encoding="utf-8")
    ast.parse(original, filename=str(DATASET_PATH))
    dataset_module = load_module(DATASET_PATH, "_dataset_original")
    original_dataset = dataset_module.create_default_dataset()
    original_examples = original_dataset.examples

    if len(original_examples) != 31:
        raise SystemExit(f"Expected 31 original examples, found {len(original_examples)}. No changes made.")
    if len(ADDITIONS) != 69:
        raise SystemExit(f"Expected 69 additions, found {len(ADDITIONS)}. No changes made.")

    original_queries = {item.query.strip().casefold() for item in original_examples}
    new_queries = [row[0].strip().casefold() for row in ADDITIONS]
    if len(original_queries) != 31 or len(set(new_queries)) != 69:
        raise SystemExit("Duplicate queries detected. No changes made.")
    duplicates = original_queries.intersection(new_queries)

    if duplicates:
        print("Queries that already exist in the original dataset:")
        for query in sorted(duplicates):
            print(" -", query)
        raise SystemExit("Duplicate query detected. No changes made.")
    if original_queries.intersection(new_queries):
        raise SystemExit("A new query duplicates an original query. No changes made.")

    for query, query_type, files, symbols, answer in ADDITIONS:
        if not query.strip() or not query_type.strip() or not answer.strip():
            raise SystemExit(f"Empty required field in row {query!r}. No changes made.")
        for relative_file in files:
            if not (ROOT / relative_file).is_file():
                raise SystemExit(f"Expected file does not exist: {relative_file}. No changes made.")

    marker = "\n    ]\n\n    return EvaluationDataset(examples)"
    if original.count(marker) != 1:
        raise SystemExit("Could not locate the examples-list insertion point. No changes made.")

    new_rows = []
    for query, query_type, files, symbols, answer in ADDITIONS:
        new_rows.extend([
            "        EvaluationExample(",
            f"            query={query!r},",
            f"            query_type={query_type!r},",
            f"            expected_files={files!r},",
            f"            expected_symbols={symbols!r},",
            f"            ground_truth_answer={answer!r},",
            "        ),",
        ])
    updated = original.replace(marker, "\n" + "\n".join(new_rows) + marker, 1)
    ast.parse(updated, filename=str(DATASET_PATH))

    # Validate the edited dataset in a temporary file before changing the original.
    temp_path = DATASET_PATH.with_name("_dataset_expansion_validation.py")
    try:
        temp_path.write_text(updated, encoding="utf-8")
        validation_module = load_module(temp_path, "_dataset_validation")
        expanded = validation_module.create_default_dataset()
        queries = [item.query.strip().casefold() for item in expanded]
        if len(expanded) != 100 or len(set(queries)) != 100:
            raise SystemExit("Pre-write validation failed; original dataset was not changed.")
    finally:
        temp_path.unlink(missing_ok=True)

    BACKUP_PATH.write_text(original, encoding="utf-8")
    try:
        DATASET_PATH.write_text(updated, encoding="utf-8")
        final_module = load_module(DATASET_PATH, "_dataset_final")
        final_dataset = final_module.create_default_dataset()
        final_queries = [item.query.strip().casefold() for item in final_dataset]
        if len(final_dataset) != 100 or len(set(final_queries)) != 100:
            raise RuntimeError("Post-write validation failed.")
    except Exception:
        DATASET_PATH.write_text(original, encoding="utf-8")
        raise

    print("Dataset expansion successful.")
    print(f"Original examples preserved: {len(original_examples)}")
    print(f"New examples added: {len(ADDITIONS)}")
    print(f"Total examples: {len(final_dataset)}")
    print(f"Unique queries: {len(set(final_queries))}")
    print(f"Backup created: {BACKUP_PATH.relative_to(ROOT)}")
    print("No benchmark was run.")


if __name__ == "__main__":
    main()
